mapper.select:
SELECT d.*, c.name AS categoryName
FROM dish AS d
LEFT JOIN category AS c ON d.category_id = c.id

    AND d.category_id = #{categoryId}
    AND d.name LIKE CONCAT('%', #{name}, '%')
    AND c.status = #{status}
